args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?parent ?parentLabel WHERE {
  {
    dbr:Nicu_Ceaușescu dbo:parent ?parent .
  } UNION {
    dbr:Nicu_Ceaușescu dbp:parents ?parent .
  } UNION {
    dbr:Nicu_Ceaușescu dbo:father ?parent .
  } UNION {
    dbr:Nicu_Ceaușescu dbp:father ?parent .
  }
  OPTIONAL { ?parent rdfs:label ?parentLabel . FILTER (lang(?parentLabel) = "en") }
}

